fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Preconditions (as stated): list is non-empty and 1 <= k < list.len()
    // We'll still defensively assert them to avoid panics from bad inputs.
    assert!(!list.is_empty(), "list must be non-empty");
    assert!(k >= 1 && k < list.len(), "k must satisfy 1 <= k < list.len()");

    let remove_idx = k - 1; // convert 1-based k to 0-based index
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // Copy prefix: indices [0 .. remove_idx)
    new_list.extend_from_slice(&list[..remove_idx]);
    // Copy suffix: indices (remove_idx .. end] => [remove_idx + 1 .. len)
    new_list.extend_from_slice(&list[remove_idx + 1..]);

    new_list
}